import React from "react";

function About() {
  return (
    <section className="max-w-5xl mx-auto text-center py-16 px-4">
      <h1 className="text-4xl font-bold mb-4 text-blue-600">About FriendFinder</h1>
      <p className="text-lg text-gray-600 leading-relaxed">
        FriendFinder helps college students and young professionals create genuine friendships 
        through shared interests, hobbies, and goals. Whether you’re new in town or just looking 
        for people to hang out with, we make it easy to connect beyond swiping.
      </p>
    </section>
  );
}

export default About;
